class Solution:
    def longestPalindromeSubseq(self, s: str) -> int:
        n = len(s)
        best = 0
        def dfs(i: int, chars: list[str]) -> None:
            nonlocal best
            if i == n:
                if chars == chars[::-1]:
                    best = max(best, len(chars))
                return
            dfs(i + 1, chars)
            chars.append(s[i])
            dfs(i + 1, chars)
            chars.pop()
        dfs(0, [])
        return best

solutions.better:
class Solution:
    def longestPalindromeSubseq(self, s: str) -> int:
        from functools import lru_cache
        @lru_cache(None)
        def dp(l: int, r: int) -> int:
            if l > r:
                return 0
            if l == r:
                return 1
            if s[l] == s[r]:
                return 2 + dp(l + 1, r - 1)
            return max(dp(l + 1, r), dp(l, r - 1))
        return dp(0, len(s) - 1)

